def T(key, lang, **kw):
    d = S[key]
    s = d.get(lang) or d["en"]
    if "{hours}" in s and "hours" not in kw:
        kw["hours"] = HOURS.get(lang, HOURS["en"])
    return s.format(**kw) if kw else s
